  }
  function duplicateNode(node: WorkflowNode) {
    const id = crypto.randomUUID();
    change({
      ...workflow,
      nodes: [
        ...workflow.nodes,
        {
          ...structuredClone(node),
          id,
          label: `${node.label} copy`,
          position: placeWorkflowStep(
            workflow,
            {
              x: node.position.x + 40,
