          actions={menuActions}
          container={root}
          trigger={contextMenu.trigger}
          onClose={() => {
            if (contextMenuRef.current !== contextMenu) return false;
            setContextMenu(null);
            return true;
          }}
        />
      )}
      {picker && editable && (
        <WorkflowStepPicker
          key={`${picker.endpoint?.nodeId ?? "trigger"}:${picker.endpoint?.port ?? ""}:${picker.point.x}:${picker.point.y}`}
          point={picker.point}
          title={
            !picker.endpoint
              ? "Choose a trigger"
              : pickerContext?.mode === "insert"
                ? "Insert a step"
                : picker.endpoint.port === "in"
                  ? "Choose the previous step"
                  : "Choose the next step"
          }
          context={
            pickerContext?.node
              ? `${pickerContext.node.label} / ${picker.endpoint?.port === "in" ? "Input" : (outputPorts(pickerContext.node).find((port) => port.id === picker.endpoint?.port)?.label ?? "Output")}`
              : undefined
          }
          choices={choices}
          container={root}
          onChoose={chooseStep}
          onClose={() => setPicker(null)}
          onRestoreFocus={() => {
            if (restorePickerFocus.current) {
              const trigger = pickerTrigger.current;
              if (trigger?.isConnected) trigger.focus({ preventScroll: true });
              else canvasElement.current?.focus({ preventScroll: true });
            }
          }}
        />
      )}
      <header className="wf-header">
        <div className="wf-identity">
          <span className="wf-identity-icon surface-control" aria-hidden="true">
            <Workflow />
          </span>
          <div>
            <h3>{workflow.name || "Untitled workflow"}</h3>
            <div
              className="wf-header-states"
              role="group"
              aria-label="Workflow status"
            >
              <WorkflowStatusIndicator
                name="publication"
                state={publicationStatus}
                label={publicationLabel}
                icon={<PublicationIcon aria-hidden="true" />}
              >
                {publicationText}
              </WorkflowStatusIndicator>
              <WorkflowStatusIndicator
                name="nodes"
                label={`Nodes: ${workflow.nodes.length}`}
                icon={<Workflow aria-hidden="true" />}
              >
                {workflow.nodes.length}{" "}
                {workflow.nodes.length === 1 ? "node" : "nodes"}
              </WorkflowStatusIndicator>
              <WorkflowStatusIndicator
                name="validation"
                state={
                  issues.length === 0
                    ? "valid"
                    : issues.length === 1
                      ? "warning"
                      : "invalid"
                }
                label={validationLabel}
                icon={
                  issues.length ? (
                    <ShieldAlert aria-hidden="true" />
                  ) : (
                    <ShieldCheck aria-hidden="true" />
                  )
                }
              >
                {issues.length} {issues.length === 1 ? "issue" : "issues"}
              </WorkflowStatusIndicator>
            </div>
          </div>
        </div>
        <WorkflowToolbar
          className="wf-actions"
          label="Workflow actions"
          grouping="separate"
        >
          {onSave && (
            <WorkflowIconButton
              variant="outline"
              label={
                busy === "save"
                  ? "Saving…"
                  : savedDefinition === serialized
                    ? `${saveLabel} (saved)`
                    : savedDefinition
                      ? `${saveLabel} (unsaved changes)`
                      : saveLabel
              }
              aria-busy={busy === "save"}
              disabled={!!busy}
              onClick={() => void action("save")}
            >
              {busy === "save" ? (
                <LoaderCircle aria-hidden="true" />
              ) : (
                <Save aria-hidden="true" />
              )}
            </WorkflowIconButton>
          )}
          {onRun &&
            (busy === "run" ? (
              <WorkflowIconButton
                variant="outline"
                label="Stop waiting"
                onClick={cancel}
              >
                <Square aria-hidden="true" />
              </WorkflowIconButton>
            ) : (
              <WorkflowIconButton
                variant="default"
                label={runLabel}
                disabled={!!busy}
                onClick={() => void action("run")}
              >
                <Play aria-hidden="true" />
              </WorkflowIconButton>
            ))}
          <Menu.Root>
            <Menu.Trigger asChild>
              <WorkflowIconButton
                data-workflow-more
                label="More workflow actions"
                touchHint={false}
              >
                <MoreHorizontal aria-hidden="true" />
              </WorkflowIconButton>
            </Menu.Trigger>
            <Menu.Portal container={expanded ? dialog.current : undefined}>
              <Menu.Content
                className="wf-menu"
                data-slot="dropdown-menu-content"
                align="end"
                sideOffset={8}
                collisionPadding={12}
                onCloseAutoFocus={(event) => {
                  const action = afterMenu.current;
                  if (!action) return;
                  event.preventDefault();
                  afterMenu.current = null;
                  root.current
                    ?.querySelector<HTMLElement>("[data-workflow-more]")
                    ?.focus();
                  action();
                }}
              >
                <Menu.Item
                  data-slot="dropdown-menu-item"
                  onSelect={() => {
                    afterMenu.current = showSettings;
                  }}
                >
                  <Settings2 aria-hidden="true" />
                  Workflow settings
                </Menu.Item>
                {onChange &&
                  templates.some((template) => template.kind === "trigger") && (
                    <Menu.Item
                      data-slot="dropdown-menu-item"
                      disabled={!editable}
                      onSelect={() => {
                        afterMenu.current = () => openTrigger(canvasCenter());
                      }}
                    >
                      <Zap aria-hidden="true" />
                      Add trigger
                    </Menu.Item>
                  )}
                {onChange && (
                  <Menu.Item
                    data-slot="dropdown-menu-item"
                    disabled={!editable || !workflow.nodes.length}
                    onSelect={() => {
                      afterMenu.current = arrange;
                    }}
                  >
                    <LayoutGrid aria-hidden="true" />
                    Arrange layout
                  </Menu.Item>
                )}
                {onChange && (
                  <Menu.Item
                    data-slot="dropdown-menu-item"
                    disabled={!editable}
                    onSelect={() => upload.current?.click()}
                  >
                    <ArrowUpFromLine aria-hidden="true" />
                    Import workflow JSON
                  </Menu.Item>
                )}
                <Menu.Item
                  data-slot="dropdown-menu-item"
                  onSelect={() => download(workflow)}
                >
                  <ArrowDownToLine aria-hidden="true" />
                  Export workflow JSON
                </Menu.Item>
              </Menu.Content>
            </Menu.Portal>
          </Menu.Root>
          <WorkflowIconButton
            data-workflow-expand
            label={expanded ? "Collapse workspace" : "Expand workspace"}
            onClick={toggleExpanded}
          >
            {expanded ? (
              <Minimize2 aria-hidden="true" />
            ) : (
              <Maximize2 aria-hidden="true" />
            )}
          </WorkflowIconButton>
        </WorkflowToolbar>
      </header>
      <input
        ref={upload}
        type="file"
        accept=".json,application/json"
        hidden
        onChange={async (event) => {
          const file = event.target.files?.[0];
          event.target.value = "";
          if (!file) return;
          if (file.size > 2_000_000) {
            setNotice("Workflow files must be no larger than 2 MB.");
            return;
          }
          try {
            const next = parseWorkflow(await file.text());
            change(next);
            closeInspector();
            setNotice("Workflow imported. You can edit it or undo the import.");
            requestAnimationFrame(() => requestAnimationFrame(fit));
          } catch (error) {
            setNotice(
              error instanceof Error
                ? error.message
                : "Could not read the workflow file.",
            );
          }
        }}
      />
      <div className="wf-stage" data-right={rightOpen}>
        <div
          ref={canvasElement}
          className="wf-canvas"
          tabIndex={0}
          aria-label="Workflow canvas"
          onContextMenu={(event) => {
            if (
              !event.defaultPrevented &&
              invokeContext(event.target as Element, {
                x: event.clientX,
                y: event.clientY,
              })
            )
              event.preventDefault();
          }}
        >
          <ReactFlow<CanvasNode, CanvasEdge>
            nodes={nodes}
            edges={edges}
            nodeTypes={nodeTypes}
            edgeTypes={edgeTypes}
            onNodeDragStart={() => {
              setPicker(null);
              setContextMenu(null);
              dragging.current = true;
              history.current.group = "";
            }}
            onNodeDragStop={() => {
              dragging.current = false;
              history.current.group = "";
            }}
            onInit={(instance) => {
              canvas.current = instance;
              setZoom(instance.getZoom());
            }}
            onNodesChange={(changes) => {
              const measurements = changes.filter(
                (item) => item.type === "dimensions" && item.dimensions,
              );
              if (measurements.length)
                setDimensions((current) => {
                  const next = { ...current };
                  let changed = false;
                  for (const item of measurements)
                    if (
                      item.type === "dimensions" &&
                      item.dimensions &&
                      (current[item.id]?.width !== item.dimensions.width ||
                        current[item.id]?.height !== item.dimensions.height)
                    ) {
                      next[item.id] = item.dimensions;
                      changed = true;
                    }
                  return changed ? next : current;
                });
              const choice = changes.find(
                (item) => item.type === "select" && item.selected,
              );
              if (choice?.type === "select" && choice.id !== selectedId)
                select(choice.id);
              const positions = changes.filter(
                (item) => item.type === "position",
              );
              if (editable && positions.length)
                change(
                  {
                    ...workflow,
                    nodes: workflow.nodes.map((node) => {
                      const move = positions.find(
                        (item) => item.id === node.id,
                      );
                      return move?.position
                        ? { ...node, position: move.position }
                        : node;
                    }),
                  },
                  `move-${positions.map((item) => item.id).join()}`,
                );
            }}
            onEdgesChange={(changes) => {
              const choice = changes.find(
                (item) => item.type === "select" && item.selected,
              );
              if (choice?.type === "select") {
                closeInspector();
                setSelectedEdge(choice.id);
              }
            }}
            onNodeClick={(_, node) => select(node.id)}
            onEdgeClick={(_, item) => selectEdge(item.id)}
            onPaneClick={() => {
              closeInspector();
            }}
            onConnect={(connection: Connection) =>
              connect({
                source: connection.source,
                target: connection.target,
                port: (connection.sourceHandle ?? "out") as WorkflowPort,
              })
            }
            onConnectEnd={onConnectEnd}
            onMoveStart={(event) => {
              if (event) {
                setPicker(null);
                setContextMenu(null);
              }
            }}
            onMove={(_, viewport) => setZoom(viewport.zoom)}
            onMoveEnd={(_, viewport) => setZoom(viewport.zoom)}
            onReconnectStart={(_, edge) => {
              reconnecting.current = edge.id;
            }}
            onReconnect={(edge, connection) =>
              changeEdge(edge as WorkflowEdge, connection)
            }
            onReconnectEnd={(_, __, ___, state) => {
              reconnecting.current = null;
              if (!state.isValid)
                setNotice("Connection unchanged. Choose a compatible port.");
            }}
            reconnectRadius={12}
            elevateEdgesOnSelect
            isValidConnection={(connection) =>
              !connectionIssue(
                reconnecting.current
                  ? {
                      ...workflow,
                      edges: workflow.edges.filter(
                        (edge) => edge.id !== reconnecting.current,
                      ),
                    }
                  : workflow,
                {
                  source: connection.source,
                  target: connection.target,
                  port: (connection.sourceHandle ?? "out") as WorkflowPort,
                },
              )
            }
            nodesDraggable={editable}
            nodesConnectable={editable}
            edgesReconnectable={editable}
            deleteKeyCode={null}
            defaultViewport={savedViewport ?? initialViewport}
            fitView={!(savedViewport ?? initialViewport)}
            fitViewOptions={{ padding: 0.1, maxZoom: 1 }}
            minZoom={0.15}
            maxZoom={1.8}
            zoomOnScroll={false}
            preventScrolling={false}
            ariaLabelConfig={ariaLabels}
          >
            <Background gap={24} size={1} />
            {workflow.nodes.length > 0 && (
              <MiniMap
                position="top-right"
                style={{ width: 112, height: 72 }}
                pannable
                zoomable
                nodeColor="var(--muted-foreground)"
                maskColor="color-mix(in srgb, var(--background) 80%, transparent)"
              />
            )}
          </ReactFlow>
          {workflow.nodes.length === 0 && (
            <div className="wf-empty">
              {editable &&
              templates.some((template) => template.kind === "trigger") ? (
                <button
                  type="button"
                  className="wf-start-node"
                  aria-haspopup="dialog"
                  onClick={(event) => {
                    const bounds = event.currentTarget.getBoundingClientRect();
                    openTrigger(
                      { x: bounds.right, y: bounds.top },
                      event.currentTarget,
                    );
                  }}
                >
                  <span>
                    <Plus aria-hidden="true" />
                  </span>
                  <strong>Choose a trigger</strong>
                  <small>Start your workflow here</small>
                </button>
              ) : (
                <div className="wf-start-node" aria-label="Empty workflow">
                  <Zap aria-hidden="true" />
                  <strong>No trigger yet</strong>
                  <small>
                    {editable
                      ? "No trigger types provided"
                      : "No workflow nodes provided"}
                  </small>
                </div>
              )}
            </div>
          )}
          {onChange && (
            <WorkflowToolbar className="wf-canvas-toolbar" label="Edit history">
              <WorkflowIconButton
                variant="outline"
                label="Undo"
                shortcut="⌘/Ctrl Z"
                disabled={!editable || !history.current.past.length}
                onClick={() => travel("past")}
              >
                <Undo2 aria-hidden="true" />
              </WorkflowIconButton>
              <WorkflowIconButton
                variant="outline"
                label="Redo"
                shortcut="⌘/Ctrl Shift Z"
                disabled={!editable || !history.current.future.length}
                onClick={() => travel("future")}
              >
                <Redo2 aria-hidden="true" />
              </WorkflowIconButton>
            </WorkflowToolbar>
          )}
          <WorkflowToolbar className="wf-zoom-controls" label="Canvas view">
            <WorkflowIconButton
              label="Zoom out"
              disabled={zoom <= 0.151}
              onClick={() =>
                void canvas.current?.zoomOut({ duration: motionDuration() })
              }
            >
              <Minus aria-hidden="true" />
            </WorkflowIconButton>
            <output
              className="wf-zoom-value"
              aria-label="Canvas zoom"
              aria-live="off"
            >
              {Math.round(zoom * 100)}%
            </output>
            <WorkflowIconButton
              label="Zoom in"
              disabled={zoom >= 1.799}
              onClick={() =>
                void canvas.current?.zoomIn({ duration: motionDuration() })
              }
            >
              <Plus aria-hidden="true" />
            </WorkflowIconButton>
            <WorkflowIconButton
              label="Fit workflow"
              disabled={!workflow.nodes.length}
              onClick={fit}
            >
              <Maximize aria-hidden="true" />
            </WorkflowIconButton>
          </WorkflowToolbar>
        </div>
        {rightOpen && (
          <aside
            className="wf-drawer wf-inspector"
            aria-label="Node and workflow configuration"
          >
            <div className="wf-drawer-heading">
              <div>
                <small>
                  {selected
                    ? workflowKinds[selected.kind].label
                    : edge
                      ? "Connection"
                      : "Workflow"}
                </small>
                <h4 ref={inspectorHeading} tabIndex={-1}>
                  {selected?.label ||
                    (edge ? "Connection details" : "Workflow settings")}
                </h4>
              </div>
              <Button
                variant="ghost"
                size="icon"
                aria-label="Close configuration"
                onClick={() => {
                  closeInspector();
                  canvasElement.current?.focus();
                }}
              >
                <X aria-hidden="true" />
              </Button>
            </div>
            {selected && (
              <NodeInspector
                node={selected}
                editable={editable}
                onInspectData={
                  result ? () => select(selected.id, true, true) : undefined
                }
                onChange={(patch) => patchNode(selected.id, patch)}
                onRemove={onChange ? () => removeNode(selected.id) : undefined}
                onDuplicate={
                  onChange ? () => duplicateNode(selected) : undefined
                }
                renderConfiguration={renderNodeConfiguration}
              />
            )}
            {edge && (
              <div className="wf-drawer-body wf-fields">
                <div className="wf-connection-field">
                  <div className="wf-field-caption">
                    <label htmlFor={`${uid}-edge-source`}>
                      Source and output
                    </label>
                    <WorkflowIconButton
                      label="Locate source node"
                      disabled={
                        !workflow.nodes.some((node) => node.id === edge.source)
                      }
                      onClick={() => select(edge.source, true)}
                    >
                      <LocateFixed aria-hidden="true" />
                    </WorkflowIconButton>
                  </div>
                  <select
                    id={`${uid}-edge-source`}
                    data-slot="select-trigger"
                    value={JSON.stringify([edge.source, edge.port])}
                    disabled={!editable}
                    onChange={(event) => {
                      const [source, port] = JSON.parse(event.target.value) as [
                        string,
                        WorkflowPort,
                      ];
                      changeEdge(edge, {
                        source,
                        sourceHandle: port,
                        target: edge.target,
                        targetHandle: "in",
                      });
                    }}
                  >
                    {!edgeSources.some(
                      (item) =>
                        item.value === JSON.stringify([edge.source, edge.port]),
                    ) && (
                      <option
                        value={JSON.stringify([edge.source, edge.port])}
                        disabled
                      >
                        {workflow.nodes.find((node) => node.id === edge.source)
                          ?.label ?? edge.source}{" "}
                        / {edge.port} (unavailable)
                      </option>
                    )}
                    {edgeSources.map((item) => (
                      <option
                        key={item.value}
                        value={item.value}
                        disabled={
                          item.disabled &&
                          item.value !==
                            JSON.stringify([edge.source, edge.port])
                        }
                      >
                        {item.label}
                      </option>
                    ))}
                  </select>
                </div>
                <div className="wf-connection-field">
                  <div className="wf-field-caption">
                    <label htmlFor={`${uid}-edge-target`}>Target node</label>
                    <WorkflowIconButton
                      label="Locate target node"
                      disabled={
                        !workflow.nodes.some((node) => node.id === edge.target)
                      }
                      onClick={() => select(edge.target, true)}
                    >
                      <LocateFixed aria-hidden="true" />
                    </WorkflowIconButton>
                  </div>
                  <select
                    id={`${uid}-edge-target`}
                    data-slot="select-trigger"
                    value={edge.target}
                    disabled={!editable}
                    onChange={(event) =>
                      changeEdge(edge, {
                        source: edge.source,
                        sourceHandle: edge.port,
                        target: event.target.value,
                        targetHandle: "in",
                      })
                    }
                  >
                    {!workflow.nodes.some(
                      (node) => node.id === edge.target,
                    ) && (
                      <option value={edge.target}>
                        {edge.target} (no longer available)
                      </option>
                    )}
                    {workflow.nodes.map((node) => (
                      <option
                        key={node.id}
                        value={node.id}
                        disabled={
                          node.id !== edge.target &&
                          !!connectionIssue(
                            {
                              ...workflow,
                              edges: workflow.edges.filter(
                                (item) => item.id !== edge.id,
                              ),
                            },
                            { ...edge, target: node.id },
                          )
                        }
                      >
                        {node.label}
                      </option>
                    ))}
                  </select>
                </div>
                {onChange && (
                  <p className="wf-field-help">
                    Occupied ports, incompatible types and connections that
                    create a cycle are unavailable. You can also drag either end
                    of the selected connection to reconnect it.
                  </p>
                )}
                <WorkflowToolbar
                  className="wf-node-actions"
                  label="Connection actions"
                >
                  {onChange && (
                    <>
                      <WorkflowIconButton
                        label="Insert a node in this connection"
                        disabled={!editable || !templates.length}
                        onClick={(event) => {
                          const box =
                            event.currentTarget.getBoundingClientRect();
                          insertOnEdge(
                            edge,
                            { x: box.left, y: box.bottom },
                            event.currentTarget,
                          );
                        }}
                      >
                        <Plus aria-hidden="true" />
                      </WorkflowIconButton>
                      <WorkflowIconButton
                        label="Remove connection"
                        disabled={!editable}
                        onClick={() => removeEdge(edge.id)}
                      >
                        <Trash2 aria-hidden="true" />
                      </WorkflowIconButton>
                    </>
                  )}
                </WorkflowToolbar>
              </div>
            )}
            {settingsOpen && (
              <div className="wf-drawer-body wf-fields">
                <label htmlFor={`${uid}-flow-name`}>
                  Workflow name
                  <input
                    data-slot="input"
                    id={`${uid}-flow-name`}
                    value={workflow.name}
                    readOnly={!editable}
                    onChange={(e) =>
                      change({ ...workflow, name: e.target.value }, "flow-name")
                    }
                  />
                </label>
                <label htmlFor={`${uid}-description`}>
                  Description
                  <textarea
                    data-slot="textarea"
                    id={`${uid}-description`}
                    value={workflow.description ?? ""}
                    readOnly={!editable}
                    rows={3}
                    onChange={(e) =>
                      change(
                        { ...workflow, description: e.target.value },
                        "flow-description",
                      )
                    }
                  />
                </label>
                <label htmlFor={`${uid}-concurrency`}>
                  Concurrency limit
                  <input
                    data-slot="input"
                    id={`${uid}-concurrency`}
                    type="number"
                    min={1}
                    max={64}
                    step={1}
                    value={workflow.maxConcurrency}
                    readOnly={!editable}
                    onChange={(e) =>
                      change(
                        { ...workflow, maxConcurrency: Number(e.target.value) },
                        "concurrency",
                      )
                    }
                  />
                  <small>
                    Maximum number of nodes that can execute at the same time in
                    one run.
                  </small>
                </label>
              </div>
            )}
          </aside>
        )}
      </div>
      <p className="wf-notice" role="status" aria-live="polite">
        {notice}
      </p>
      {(onRun || result) && (
        <WorkflowRunResults
          id={`${uid}-results`}
          workflow={workflow}
          run={result}
          pending={busy === "run"}
          message={runMessage}
          open={consoleOpen}
          onOpenChange={setConsoleOpen}
          selectedId={resultNodeId}
          onSelect={setResultNodeId}
          view={resultView}
          onViewChange={setResultView}
          onLocate={locate}
          onConfigure={(id) => select(id, true)}
        />
      )}
    </section>
  );
  return (
    <WorkflowTooltips container={root}>
      {!expanded && editor}
      <dialog
        ref={dialog}
        className="wf-expanded"
        aria-label="Expanded workflow workspace"
        onCancel={(event) => {
          event.preventDefault();
          setSavedViewport(canvas.current?.getViewport());
          setExpanded(false);
        }}
      >
        {expanded && editor}
      </dialog>
    </WorkflowTooltips>
  );
}

"use client";

import {
  createContext,
  useContext,
  useEffect,
  useId,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
  type ReactElement,
  type RefObject,
} from "react";
import { DropdownMenu as Menu, Popover, Toolbar, Tooltip } from "radix-ui";
import {
  Check,
  Braces,
  ChevronDown,
  CircleAlert,
  CircleHelp,
  Clock3,
  LoaderCircle,
  LocateFixed,
  Filter,
  Minus,
  Search,
  Square,
  Settings2,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  formatWorkflowSummaryValue,
  workflowKinds,
  workflowStatuses,
  type WorkflowNode,
  type WorkflowDefinition,
  type WorkflowRun,
  type WorkflowNodeRun,
  type WorkflowNodeSummary,
  type WorkflowStatus,
} from "./workflow-model";

export type WorkflowStepChoice = {
  id: string;
  label: string;
  description: string;
  group: string;
  icon: ReactNode;
  existing?: boolean;
};

export type WorkflowMenuAction = {
  id: string;
  label: string;
  icon: ReactNode;
  disabled?: boolean;
  destructive?: boolean;
  separator?: boolean;
  onSelect: () => void;
};

/** Same menu behavior and material as the toolbar, anchored to the invoked object. */
export function WorkflowContextMenu({
  point,
  label,
  actions,
  container,
  trigger,
  onClose,
}: {
  point: { x: number; y: number };
  label: string;
  actions: WorkflowMenuAction[];
  container: RefObject<HTMLElement | null>;
  trigger: HTMLElement;
  onClose: () => boolean;
}) {
  const [open, setOpen] = useState(true);
  const selected = useRef<(() => void) | undefined>(undefined);
  const restore = useRef(true);
  return (
    <Menu.Root open={open} onOpenChange={setOpen} modal={false}>
      <Menu.Trigger asChild>
        <span
          className="wf-context-anchor"
          aria-hidden="true"
          tabIndex={-1}
          style={{ left: point.x, top: point.y }}
        />
      </Menu.Trigger>
      <Menu.Portal container={container.current}>
        <Menu.Content
          className="wf-menu wf-context-menu"
          data-slot="dropdown-menu-content"
          aria-label={label}
          aria-labelledby={undefined}
          align="start"
          sideOffset={4}
          collisionPadding={12}
          onEscapeKeyDown={(event) => event.stopPropagation()}
          onInteractOutside={() => {
            restore.current = false;
          }}
          onCloseAutoFocus={(event) => {
            event.preventDefault();
            if (!onClose()) return;
            if ((selected.current || restore.current) && trigger.isConnected)
              trigger.focus({ preventScroll: true });
            selected.current?.();
          }}
        >
          <Menu.Label className="wf-menu-label">{label}</Menu.Label>
          {actions.map((action) => (
            <div key={action.id}>
              {action.separator && (
                <Menu.Separator data-slot="dropdown-menu-separator" />
              )}
              <Menu.Item
                data-slot="dropdown-menu-item"
                data-variant={action.destructive ? "destructive" : undefined}
                disabled={action.disabled}
                onSelect={() => {
                  selected.current = action.onSelect;
                }}
              >
                {action.icon}
                <span>{action.label}</span>
              </Menu.Item>
            </div>
          ))}
        </Menu.Content>
      </Menu.Portal>
    </Menu.Root>
  );
}

/** A searchable dialog: Tab remains usable; arrows also move between choices. */
export function WorkflowStepPicker({
  point,
  title,
  context,
  choices,
  container,
  onChoose,
  onClose,
  onRestoreFocus,
}: {
  point: { x: number; y: number };
  title: string;
  context?: string;
  choices: WorkflowStepChoice[];
  container: RefObject<HTMLElement | null>;
  onChoose: (id: string) => void;
  onClose: () => void;
  onRestoreFocus: () => void;
}) {
  const uid = useId();
  const [query, setQuery] = useState("");
  const [tab, setTab] = useState("new");
  const search = useRef<HTMLInputElement>(null);
  const content = useRef<HTMLDivElement>(null);
  const restoreOnClose = useRef(true);
  const anchor = useRef({
    getBoundingClientRect: () => new DOMRect(point.x, point.y, 0, 0),
  });
  anchor.current = {
    getBoundingClientRect: () => new DOMRect(point.x, point.y, 0, 0),
  };
  const hasExisting = choices.some((choice) => choice.existing);
  const renderChoices = (existing: boolean) => {
    const filtered = choices.filter(
      (choice) =>
        !!choice.existing === existing &&
        `${choice.label} ${choice.description} ${choice.group}`
          .toLowerCase()
          .includes(query.trim().toLowerCase()),
    );
    return (
      <>
        {[...new Set(filtered.map((choice) => choice.group))].map((group) => (
          <div
            className="wf-step-group"
            role="group"
            aria-label={group}
            key={group}
          >
            <small aria-hidden="true">{group}</small>
            {filtered
              .filter((choice) => choice.group === group)
              .map((choice) => (
                <button
                  type="button"
                  key={choice.id}
                  data-step-choice={choice.id}
                  onClick={() => onChoose(choice.id)}
                >
                  {choice.icon}
                  <span>
                    <strong>{choice.label}</strong>
                    <small>{choice.description}</small>
                  </span>
                </button>
              ))}
          </div>
        ))}
        {!filtered.length && (
          <p className="wf-step-empty">
            {query ? "No matching nodes" : "No compatible nodes"}
          </p>
        )}
      </>
    );
  };
  return (
    <Popover.Root
      open
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
    >
      <Popover.Anchor virtualRef={anchor} />
      <Popover.Portal container={container.current}>
        <Popover.Content
          ref={content}
          className="wf-step-picker"
          side="bottom"
          align="start"
          sideOffset={10}
          collisionPadding={12}
          aria-labelledby={`${uid}-title`}
          aria-describedby={context ? `${uid}-context` : undefined}
          onOpenAutoFocus={(event) => {
            event.preventDefault();
            search.current?.focus();
          }}
          onCloseAutoFocus={(event) => {
            event.preventDefault();
            const active = document.activeElement;
            if (
              restoreOnClose.current &&
              (!active ||
                active === document.body ||
                content.current?.contains(active))
            )
              onRestoreFocus();
          }}
          onInteractOutside={() => {
            restoreOnClose.current = false;
          }}
          onEscapeKeyDown={(event) => event.stopPropagation()}
          onKeyDown={(event) => {
            if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key))
              return;
            const inSearch = event.target === search.current;
            if (inSearch && (event.key === "Home" || event.key === "End"))
              return;
            if (
              !inSearch &&
              !(event.target as HTMLElement).closest("[data-step-choice]")
            )
              return;
            const buttons = Array.from(
              content.current?.querySelectorAll<HTMLButtonElement>(
                "[data-step-choice]",
              ) ?? [],
            );
            if (!buttons.length) return;
            event.preventDefault();
            event.stopPropagation();
            const current = buttons.indexOf(
              document.activeElement as HTMLButtonElement,
            );
            const next =
              event.key === "Home"
                ? 0
                : event.key === "End"
                  ? buttons.length - 1
                  : current < 0
                    ? event.key === "ArrowUp"
                      ? buttons.length - 1
                      : 0
                    : (current +
                        (event.key === "ArrowUp" ? -1 : 1) +
                        buttons.length) %
                      buttons.length;
            buttons[next].focus();
          }}
        >
          <div className="wf-step-picker-heading">
            <strong id={`${uid}-title`}>{title}</strong>
            {context && <small id={`${uid}-context`}>{context}</small>}
          </div>
          <label className="wf-search">
            <Search aria-hidden="true" />
            <input
              data-slot="input"
              ref={search}
              aria-label="Search compatible nodes"
              placeholder="Search nodes…"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
            />
          </label>
          {hasExisting ? (
            <Tabs className="wf-step-tabs" value={tab} onValueChange={setTab}>
              <TabsList aria-label="Choose node source">
                <TabsTrigger value="new">New node</TabsTrigger>
                <TabsTrigger value="existing">Connect existing</TabsTrigger>
              </TabsList>
              <TabsContent value="new" className="wf-step-choices">
                {renderChoices(false)}
              </TabsContent>
              <TabsContent value="existing" className="wf-step-choices">
                {renderChoices(true)}
              </TabsContent>
            </Tabs>
          ) : (
            <div className="wf-step-choices">{renderChoices(false)}</div>
          )}
        </Popover.Content>
      </Popover.Portal>
    </Popover.Root>
  );
}

export function NodeSummary({ summary }: { summary: WorkflowNodeSummary }) {
  if (summary.type === "expression")
    return (
      <div className="wf-node-summary wf-node-expression">
        <span>{summary.subject}</span>
        <strong>
          <span className="wf-node-operator">{summary.operator}</span>
          {formatWorkflowSummaryValue(summary.value, summary.unit)}
        </strong>
      </div>
    );
  return (
    <dl className="wf-node-summary wf-node-fields">
      {summary.fields.slice(0, 3).map((field, index) => (
        <div key={`${index}-${field.label}`}>
          <dt>{field.label}</dt>
          <dd>{formatWorkflowSummaryValue(field.value, field.unit)}</dd>
        </div>
      ))}
    </dl>
  );
}

const TooltipContainer = createContext<RefObject<HTMLElement | null> | null>(
  null,
);
const InWorkflowToolbar = createContext(false);

export function WorkflowToolbar({
