export function WorkflowIconButton({
  label,
  shortcut,
  touchHint = true,
  children,
  ...props
}: Omit<ComponentProps<typeof Button>, "size" | "title" | "aria-label"> & {
  label: string;
  shortcut?: string;
  touchHint?: boolean;
}) {
  const container = useContext(TooltipContainer);
  const inToolbar = useContext(InWorkflowToolbar);
  const [open, setOpen] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const held = useRef(false);
  const start = useRef({ x: 0, y: 0 });
  const clearHold = () => clearTimeout(timer.current);
  useEffect(() => clearHold, []);
  const button = (
    <Button
      variant="ghost"
      {...props}
      size="icon"
      aria-label={label}
      onPointerDown={(event) => {
        props.onPointerDown?.(event);
        clearHold();
        held.current = false;
        if (
          !touchHint ||
          event.pointerType !== "touch" ||
          event.defaultPrevented
        )
          return;
        start.current = { x: event.clientX, y: event.clientY };
        timer.current = setTimeout(() => {
          held.current = true;
          setOpen(true);
        }, 450);
      }}
      onPointerMove={(event) => {
        props.onPointerMove?.(event);
        if (
          Math.hypot(
            event.clientX - start.current.x,
            event.clientY - start.current.y,
          ) > 8
        )
          clearHold();
      }}
      onPointerUp={(event) => {
        clearHold();
        props.onPointerUp?.(event);
      }}
      onPointerCancel={(event) => {
        clearHold();
        held.current = false;
        setOpen(false);
        props.onPointerCancel?.(event);
      }}
      onContextMenu={(event) => {
        if (held.current) event.preventDefault();
        props.onContextMenu?.(event);
      }}
      onClick={(event) => {
        if (held.current) {
          held.current = false;
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        props.onClick?.(event);
      }}
    >
      {children}
    </Button>
  );
  return (
    <Tooltip.Root open={open} onOpenChange={setOpen}>
      <Tooltip.Trigger asChild>
        {inToolbar ? (
          <Toolbar.Button asChild disabled={props.disabled}>
            {button}
          </Toolbar.Button>
        ) : (
          button
        )}
      </Tooltip.Trigger>
      <Tooltip.Portal container={container?.current}>
        <Tooltip.Content
          className="wf-tooltip"
          data-slot="tooltip-content"
          sideOffset={8}
          collisionPadding={12}
          onEscapeKeyDown={(event) => event.stopPropagation()}
        >
          {label}
          {shortcut && <kbd>{shortcut}</kbd>}
        </Tooltip.Content>
      </Tooltip.Portal>
    </Tooltip.Root>
  );
}

/** Shared hint behavior for status indicators and dense rows. */
export function WorkflowHint({
  label,
  children,
  touchHint = false,
}: {
  label: string;
  children: ReactElement;
  touchHint?: boolean;
}) {
  const container = useContext(TooltipContainer);
  const [open, setOpen] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const held = useRef(false);
  const start = useRef({ x: 0, y: 0 });
  const clearHold = () => clearTimeout(timer.current);
  useEffect(() => clearHold, []);
  return (
    <Tooltip.Root open={open} onOpenChange={setOpen}>
      <Tooltip.Trigger
        asChild
        onPointerDown={(event) => {
          clearHold();
          held.current = false;
          if (!touchHint || event.pointerType !== "touch") return;
          start.current = { x: event.clientX, y: event.clientY };
          timer.current = setTimeout(() => {
            held.current = true;
            setOpen(true);
          }, 450);
        }}
        onPointerMove={(event) => {
          if (
            Math.hypot(
              event.clientX - start.current.x,
              event.clientY - start.current.y,
            ) > 8
          )
            clearHold();
        }}
        onPointerUp={clearHold}
        onPointerCancel={() => {
          clearHold();
          held.current = false;
          setOpen(false);
        }}
        onContextMenu={(event) => {
          if (held.current) event.preventDefault();
        }}
        onClick={(event) => {
          if (!held.current) return;
          held.current = false;
          event.preventDefault();
          event.stopPropagation();
        }}
      >
        {children}
      </Tooltip.Trigger>
      <Tooltip.Portal container={container?.current}>
        <Tooltip.Content
          className="wf-tooltip"
          data-slot="tooltip-content"
          sideOffset={8}
          collisionPadding={12}
          onEscapeKeyDown={(event) => event.stopPropagation()}
        >
          {label}
        </Tooltip.Content>
      </Tooltip.Portal>
    </Tooltip.Root>
  );
}

