export function RunStatus({
  status,
  iconOnly = false,
}: {
  status: WorkflowStatus;
  iconOnly?: boolean;
}) {
  const Icon = {
    pending: Clock3,
    running: LoaderCircle,
    succeeded: Check,
    failed: CircleAlert,
    skipped: Minus,
    cancelled: Square,
  }[status];
  return (
    <span className="wf-status" data-status={status}>
      <Icon aria-hidden="true" />
      <span className={iconOnly ? "sr-only" : undefined}>
        {workflowStatuses[status]}
      </span>
    </span>
  );
}

export function utcTime(value?: string) {
  if (!value) return "—";
  const time = new Date(value);
  return Number.isFinite(time.getTime())
    ? time.toISOString().replace("T", " ").replace("Z", " UTC")
    : "Invalid time";
}

export function duration(
  entry?: Pick<WorkflowNodeRun, "startedAt" | "finishedAt">,
) {
  if (!entry?.startedAt || !entry.finishedAt) return "—";
  const ms = Date.parse(entry.finishedAt) - Date.parse(entry.startedAt);
  return Number.isFinite(ms) && ms >= 0
    ? ms < 1000
      ? `${ms} ms`
      : `${(ms / 1000).toFixed(2)} s`
    : "—";
}

function Payload({ label, value }: { label: string; value: unknown }) {
  let formatted = "Not provided";
  try {
    formatted =
      value === undefined
        ? "Not provided"
        : (JSON.stringify(value, null, 2) ?? "Not provided");
  } catch {
    formatted = "Data cannot be serialized";
  }
  return (
    <section className="wf-payload">
      <h4>{label}</h4>
      <pre tabIndex={0} aria-label={label}>
        {formatted}
      </pre>
    </section>
  );
}

/** A single matching execution receipt, not an execution-history or replay service. */
export function WorkflowRunResults({
  id,
  workflow,
  run,
  pending,
  message,
  open,
  onOpenChange,
  selectedId,
  onSelect,
  onLocate,
  onConfigure,
  view,
  onViewChange,
}: {
  id: string;
  workflow: WorkflowDefinition;
  run?: WorkflowRun;
  pending: boolean;
  message: string | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  selectedId: string | null;
  onSelect: (id: string) => void;
  onLocate: (id: string) => void;
  onConfigure: (id: string) => void;
  view: { failuresOnly: boolean; payloadTab: string };
  onViewChange: (view: { failuresOnly: boolean; payloadTab: string }) => void;
}) {
  const { failuresOnly, payloadTab } = view;
  const nodeList = useRef<HTMLUListElement>(null);
  const entries = new Map(run?.nodes.map((entry) => [entry.nodeId, entry]));
  const rows = [
    ...workflow.nodes.map((node) => ({
      id: node.id,
      label: node.label,
      node,
      entry: entries.get(node.id),
    })),
    ...(
      run?.nodes.filter(
        (entry) => !workflow.nodes.some((node) => node.id === entry.nodeId),
      ) ?? []
    ).map((entry) => ({
      id: entry.nodeId,
      label: entry.nodeId,
      node: undefined,
      entry,
    })),
  ];
  const failures = rows.filter((row) => row.entry?.status === "failed");
  const visibleRows = failuresOnly && failures.length ? failures : rows;
  const latestCompleted = visibleRows
    .filter((row) => row.entry?.status === "succeeded")
    .sort(
      (a, b) =>
        (Date.parse(b.entry?.finishedAt ?? "") || 0) -
        (Date.parse(a.entry?.finishedAt ?? "") || 0),
    )[0];
  // Follow the first failure/running node until the user deliberately selects a node.
  const active =
    visibleRows.find((row) => row.id === selectedId) ??
    visibleRows.find((row) => row.entry?.status === "failed") ??
    visibleRows.find((row) => row.entry?.status === "running") ??
    latestCompleted ??
    visibleRows.find((row) => row.entry) ??
    visibleRows[0];
  const entry = active?.entry;
  useEffect(() => {
    const list = nodeList.current;
    const current = list?.querySelector<HTMLElement>('[aria-current="true"]');
    if (!open || !list || !current) return;
    const bounds = list.getBoundingClientRect();
    const item = current.getBoundingClientRect();
    // Keep selection in the local list without scrolling the page or moving focus.
    if (item.top < bounds.top) list.scrollTop += item.top - bounds.top;
    else if (item.bottom > bounds.bottom)
      list.scrollTop += item.bottom - bounds.bottom;
  }, [active?.id, open, failuresOnly]);
  return (
    <section className="wf-results" aria-label="Run results">
      <button
        type="button"
        className="wf-results-toggle"
        aria-expanded={open}
        aria-controls={id}
        onClick={() => onOpenChange(!open)}
      >
        <Braces aria-hidden="true" />
        <span>Run results</span>
        <span className="wf-results-summary" role="status">
          {run ? (
            <>
              <RunStatus status={run.status} />
              <span>Total duration {duration(run)}</span>
            </>
          ) : (
            <span>
              {pending
                ? "Waiting for run results…"
                : message
                  ? "Run result unavailable"
                  : "Not tested"}
            </span>
          )}
        </span>
        <ChevronDown
          className={open ? "wf-chevron-open" : ""}
          aria-hidden="true"
        />
      </button>
      {open && (
        <div id={id} className="wf-results-body">
          {message && (
            <p className="wf-run-message" role="status">
              {message}
            </p>
          )}
          {run ? (
            <>
              <details className="wf-run-context">
                <summary>
                  Run details<span>{utcTime(run.startedAt)}</span>
                </summary>
                <dl className="wf-definition">
                  <dt>Run ID</dt>
                  <dd>{run.id}</dd>
                  <dt>Started</dt>
                  <dd>{utcTime(run.startedAt)}</dd>
                  <dt>Finished</dt>
                  <dd>{utcTime(run.finishedAt)}</dd>
                </dl>
              </details>
              <div className="wf-run-workspace">
                <div className="wf-run-navigation">
                  <div className="wf-run-list-heading">
                    <h4>
                      Nodes <span>{rows.length}</span>
                    </h4>
                    {!!failures.length && (
                      <WorkflowIconButton
                        label={`Failed nodes only (${failures.length})`}
                        aria-pressed={failuresOnly}
                        variant={failuresOnly ? "outline" : "ghost"}
                        onClick={() =>
                          onViewChange({ ...view, failuresOnly: !failuresOnly })
                        }
                      >
                        <Filter aria-hidden="true" />
                      </WorkflowIconButton>
                    )}
                  </div>
                  <ul
                    ref={nodeList}
                    className="wf-run-node-list"
                    aria-label="Run nodes"
                  >
                    {visibleRows.map((row) => (
                      <li key={row.id}>
                        <WorkflowHint
                          label={`${row.label}, ${row.entry ? workflowStatuses[row.entry.status] : "No result provided"}, duration ${duration(row.entry)}`}
                        >
                          <button
                            type="button"
                            aria-current={
                              active?.id === row.id ? "true" : undefined
                            }
                            data-run-node={row.id}
                            onClick={() => onSelect(row.id)}
                          >
                            {row.entry ? (
                              <RunStatus status={row.entry.status} iconOnly />
                            ) : (
                              <span
                                className="wf-status"
                                data-status="unreported"
                              >
                                <CircleHelp aria-hidden="true" />
                                <span className="sr-only">
                                  No result provided
                                </span>
                              </span>
                            )}
                            <span className="wf-run-node-label">
                              {row.label}
                            </span>
                            <span className="wf-run-node-duration">
                              {duration(row.entry)}
                            </span>
                          </button>
                        </WorkflowHint>
                      </li>
                    ))}
                  </ul>
                </div>
                <section
                  className="wf-result-detail"
                  aria-label="Node execution data"
                >
                  {active ? (
                    <>
                      <header className="wf-result-heading">
                        <h4 tabIndex={-1}>{active.label}</h4>
                        {active.node && (
                          <div data-slot="control-row">
                            <WorkflowIconButton
                              label="Locate on canvas"
                              onClick={() => onLocate(active.id)}
                            >
                              <LocateFixed aria-hidden="true" />
                            </WorkflowIconButton>
                            <WorkflowIconButton
                              label="View node configuration"
                              onClick={() => onConfigure(active.id)}
                            >
                              <Settings2 aria-hidden="true" />
                            </WorkflowIconButton>
                          </div>
                        )}
                      </header>
                      {entry ? (
                        <>
                          <div className="wf-result-meta">
                            <RunStatus status={entry.status} />
                            <span>Duration {duration(entry)}</span>
                            <span>Attempts {entry.attempts ?? "—"} </span>
                          </div>
                          {entry.message && (
                            <p
                              className="wf-result-message"
                              data-failed={entry.status === "failed"}
                            >
                              {entry.message}
                            </p>
                          )}
                          <Tabs
                            value={payloadTab}
                            onValueChange={(payloadTab) =>
                              onViewChange({ ...view, payloadTab })
                            }
                            className="wf-result-data"
                          >
                            <TabsList
                              variant="line"
                              aria-label="Execution data"
                            >
                              <TabsTrigger value="input">Input</TabsTrigger>
                              <TabsTrigger value="output">Output</TabsTrigger>
                              <TabsTrigger value="timing">
                                Execution info
                              </TabsTrigger>
                            </TabsList>
                            <TabsContent value="input">
                              <Payload label="Input data" value={entry.input} />
                            </TabsContent>
                            <TabsContent value="output">
                              <Payload
                                label="Output data"
                                value={entry.output}
                              />
                            </TabsContent>
                            <TabsContent value="timing">
                              <dl className="wf-definition">
                                <dt>Node ID</dt>
                                <dd>{entry.nodeId}</dd>
                                <dt>Started</dt>
                                <dd>{utcTime(entry.startedAt)}</dd>
                                <dt>Finished</dt>
                                <dd>{utcTime(entry.finishedAt)}</dd>
                              </dl>
                            </TabsContent>
                          </Tabs>
                        </>
                      ) : (
                        <p className="wf-run-empty">
                          No result was provided for this node, so its execution
                          status is unknown.
                        </p>
                      )}
                    </>
                  ) : (
                    <p className="wf-run-empty">
                      This run contains no node records.
                    </p>
                  )}
                </section>
              </div>
            </>
          ) : (
            <p className="wf-run-empty">
              {pending
                ? "Node status and data will appear when execution results arrive."
                : message
                  ? "You can test the workflow again."
                  : "Test the workflow to inspect node inputs, outputs and failures here."}
            </p>
          )}
        </div>
      )}
    </section>
  );
}

export function NodeInspector({
  node,
  editable,
  onInspectData,
  onChange,
  onRemove,
  onDuplicate,
  renderConfiguration,
}: {
  node: WorkflowNode;
  editable: boolean;
  onInspectData?: () => void;
  onChange: (patch: Partial<WorkflowNode>) => void;
  onRemove?: () => void;
  onDuplicate?: () => void;
  renderConfiguration?: (
    node: WorkflowNode,
    context: {
      readOnly: boolean;
      onChange: (patch: Partial<WorkflowNode>) => void;
    },
  ) => ReactNode;
}) {
  const uid = useId();
  return (
    <div className="wf-drawer-body wf-fields">
      {onInspectData && (
        <Button variant="outline" onClick={onInspectData}>
          <Braces aria-hidden="true" />
          View execution data
        </Button>
      )}
      <label htmlFor={`${uid}-name`}>
        Node name
        <input
          data-slot="input"
          id={`${uid}-name`}
          value={node.label}
          readOnly={!editable}
          onChange={(e) => onChange({ label: e.target.value })}
        />
      </label>
      {node.kind === "parallel" && (
        <p className="wf-field-help">
          Send the same input to each branch and execute them in parallel.
        </p>
      )}
      {node.kind === "join" && (
        <label htmlFor={`${uid}-join`}>
          Wait policy
          <select
            data-slot="select-trigger"
            id={`${uid}-join`}
            disabled={!editable}
            value={node.joinMode ?? ""}
            onChange={(e) =>
              onChange({ joinMode: e.target.value as "all" | "any" })
            }
          >
            <option value="" disabled>
              Choose a wait policy
            </option>
            <option value="all">Wait for all branches to succeed</option>
            <option value="any">
              Continue after the first successful branch
            </option>
          </select>
          <small>
            {node.joinMode === "any"
              ? "Other branches continue running and are not cancelled automatically."
              : "The join fails if any branch fails, and is skipped if a branch is skipped."}
          </small>
        </label>
      )}
      {renderConfiguration
        ? renderConfiguration(node, { readOnly: !editable, onChange })
        : node.parameters.map((field, index) => {
            const id = `${uid}-parameter-${index}`;
            const setValue = (value: string) =>
              onChange({
                parameters: node.parameters.map((entry, i) =>
                  i === index
                    ? {
                        ...entry,
                        value:
                          field.type === "number"
                            ? value === ""
                              ? null
                              : Number(value)
                            : value,
                      }
                    : entry,
                ),
              });
            return (
              <label key={field.key} htmlFor={id}>
                {field.label}
                {field.required && (
                  <span className="wf-required" aria-hidden="true">
                    {" "}
                    *
                  </span>
                )}
                {field.type === "select" ? (
                  <select
                    data-slot="select-trigger"
                    id={id}
                    disabled={!editable}
                    value={String(field.value ?? "")}
                    required={field.required}
                    aria-describedby={
                      field.description ? `${id}-hint` : undefined
                    }
                    onChange={(e) => setValue(e.target.value)}
                  >
                    {field.value === null && (
                      <option value="">Select an option</option>
                    )}
                    {field.options?.map((option) => (
                      <option key={option.value} value={option.value}>
                        {option.label}
                      </option>
                    ))}
                  </select>
                ) : (
                  <input
                    data-slot="input"
                    id={id}
                    type={field.type === "number" ? "number" : "text"}
                    min={field.min}
                    max={field.max}
                    step={field.type === "number" ? "any" : undefined}
                    value={field.value === null ? "" : String(field.value)}
                    required={field.required}
                    readOnly={!editable}
                    aria-describedby={
                      field.description ? `${id}-hint` : undefined
                    }
                    onChange={(e) => setValue(e.target.value)}
                  />
                )}
                {field.description && (
                  <small id={`${id}-hint`}>{field.description}</small>
                )}
              </label>
            );
          })}
      <details className="wf-advanced">
        <summary>Execution policy</summary>
        <div className="wf-fields">
          <label htmlFor={`${uid}-timeout`}>
            Timeout (ms)
            <input
              data-slot="input"
              id={`${uid}-timeout`}
              type="number"
              min={1}
              step={1}
              value={node.timeoutMs}
              readOnly={!editable}
              onChange={(e) => onChange({ timeoutMs: Number(e.target.value) })}
            />
          </label>
          <label htmlFor={`${uid}-attempts`}>
            Maximum attempts
            <input
              data-slot="input"
              id={`${uid}-attempts`}
              type="number"
              min={1}
              max={10}
              step={1}
              value={node.maxAttempts}
              readOnly={!editable}
              onChange={(e) =>
                onChange({ maxAttempts: Number(e.target.value) })
              }
            />
          </label>
          <small>
            Retries may deliver data more than once. The execution service must
            ensure idempotency.
          </small>
        </div>
      </details>
      <details className="wf-advanced">
        <summary>Node definition</summary>
        <dl className="wf-definition">
          <dt>Type</dt>
          <dd>{workflowKinds[node.kind].label}</dd>
          <dt>Handler</dt>
          <dd>{node.operation}</dd>
          <dt>Input</dt>
          <dd>{node.inputType ?? "Not declared"}</dd>
          <dt>Output</dt>
          <dd>{node.outputType ?? "Not declared"}</dd>
        </dl>
        {node.description && (
          <p className="wf-field-help">{node.description}</p>
        )}
      </details>
      {(onRemove || onDuplicate) && (
        <div className="wf-node-actions" data-slot="control-row">
          {onDuplicate && (
            <Button
              variant="outline"
              disabled={!editable}
              onClick={onDuplicate}
            >
              Duplicate node
            </Button>
          )}
          {onRemove && (
            <Button variant="ghost" disabled={!editable} onClick={onRemove}>
              Remove node
            </Button>
          )}
        </div>
      )}
    </div>
  );
}

/** Portable workflow definition. No transport, credentials, scheduler or fixtures. */
export type WorkflowKind =
  | "trigger"
  | "source"
  | "quality"
  | "transform"
  | "aggregate"
  | "model"
  | "condition"
  | "parallel"
  | "join"
  | "sink"
  | "failure";
export type WorkflowValue = string | number | boolean | null;
/** Presentation derived from current configuration, never a second stored configuration. */
export type WorkflowSummaryField = {
  label: string;
  value: WorkflowValue;
  /** Only provide a unit defined by the adapter's data contract. */
  unit?: string;
};
export type WorkflowNodeSummary =
  | { type: "fields"; fields: readonly WorkflowSummaryField[] }
  | {
      type: "expression";
      subject: string;
      operator: string;
      value: WorkflowValue;
      unit?: string;
    };
export type WorkflowParameter = {
  key: string;
  label: string;
  type: "text" | "number" | "select";
  value: WorkflowValue;
  description?: string;
  required?: boolean;
  min?: number;
  max?: number;
  options?: { label: string; value: string }[];
};
export type WorkflowNode = {
  id: string;
  kind: WorkflowKind;
  label: string;
  description?: string;
  /** Adapter identifier supplied by the application; never evaluated as code. */
  operation: string;
  position: { x: number; y: number };
  inputType?: string;
  outputType?: string;
  parameters: WorkflowParameter[];
  joinMode?: "all" | "any";
  timeoutMs: number;
  maxAttempts: number;
};
export type WorkflowTemplate = Omit<WorkflowNode, "id" | "position"> & {
  id: string;
};
export type WorkflowPort = "out" | "true" | "false" | "error";
export type WorkflowEdge = {
  id: string;
  source: string;
  target: string;
  port: WorkflowPort;
};
export type WorkflowDefinition = {
  schemaVersion: 1;
  id: string;
  name: string;
  description?: string;
  maxConcurrency: number;
  nodes: WorkflowNode[];
  edges: WorkflowEdge[];
};
/** Publication metadata belongs to the host, separate from draft persistence. */
export type WorkflowPublication =
  | { workflowId: string; status: "draft" }
  | {
      workflowId: string;
      status: "published";
      /** Signature of the definition actually published, excluding canvas layout. */
      definitionSignature: string;
    };

export function workflowPublicationStatus(
  workflow: WorkflowDefinition,
  publication?: WorkflowPublication,
): "unknown" | "draft" | "published" | "changed" {
  if (!publication || publication.workflowId !== workflow.id) return "unknown";
  if (publication.status === "draft") return "draft";
  return publication.definitionSignature === workflowSignature(workflow)
    ? "published"
    : "changed";
}
export type WorkflowStatus =
  "pending" | "running" | "succeeded" | "failed" | "skipped" | "cancelled";
export type WorkflowNodeRun = {
  nodeId: string;
  status: WorkflowStatus;
  startedAt?: string;
  finishedAt?: string;
  attempts?: number;
  input?: unknown;
  output?: unknown;
  message?: string;
};
export type WorkflowRun = {
  id: string;
  workflowId: string;
  /** workflowSignature(definition), captured at dispatch; not a security hash. */
  definitionSignature: string;
  status: WorkflowStatus;
  startedAt: string;
  finishedAt?: string;
  nodes: WorkflowNodeRun[];
};
export type WorkflowRunContext = {
  signal: AbortSignal;
  onUpdate: (run: WorkflowRun) => void;
};
export type WorkflowIssue = {
  code: string;
  message: string;
  nodeId?: string;
  edgeId?: string;
};

export const workflowKinds: Record<
  WorkflowKind,
  { label: string; group: string }
> = {
  trigger: { label: "Event trigger", group: "Triggers and inputs" },
  source: { label: "Data source", group: "Triggers and inputs" },
  quality: { label: "Quality check", group: "Data processing" },
  transform: { label: "Transform", group: "Data processing" },
  aggregate: { label: "Window aggregate", group: "Data processing" },
  model: { label: "Model inference", group: "Data processing" },
  condition: { label: "Condition", group: "Flow control" },
  parallel: { label: "Parallel split", group: "Flow control" },
  join: { label: "Join", group: "Flow control" },
  sink: { label: "Delivery", group: "Outputs and errors" },
  failure: { label: "Error handler", group: "Outputs and errors" },
};
export const workflowStatuses: Record<WorkflowStatus, string> = {
  pending: "Queued",
  running: "Running",
  succeeded: "Succeeded",
  failed: "Failed",
  skipped: "Skipped",
  cancelled: "Cancelled",
};
export function formatWorkflowSummaryValue(
  value: WorkflowValue,
  unit?: string,
) {
  if (value === null) return "Not configured";
  if (value === "") return "Empty text";
  if (typeof value === "number" && !Number.isFinite(value))
    return "Invalid value";
  return `${String(value)}${unit ? ` ${unit}` : ""}`;
}

/** Only summarize semantics owned by the editor; adapter parameter keys are opaque. */
export function defaultWorkflowNodeSummary(
  node: WorkflowNode,
  workflow: WorkflowDefinition,
): WorkflowNodeSummary {
  if (node.kind === "parallel")
    return {
      type: "fields",
      fields: [
        {
          label: "Branches",
          value: workflow.edges.filter(
            (edge) => edge.source === node.id && edge.port === "out",
          ).length,
        },
        { label: "Concurrency", value: workflow.maxConcurrency },
      ],
    };
  if (node.kind === "join")
    return {
      type: "fields",
      fields: [
        {
          label: "Wait for",
          value:
            node.joinMode === "any"
              ? "Any input to succeed"
              : "All inputs to succeed",
        },
        {
          label: "Input",
          value: workflow.edges.filter((edge) => edge.target === node.id)
            .length,
        },
      ],
    };
  return {
    type: "fields",
    fields: [{ label: "Parameters", value: node.parameters.length }],
  };
}

export function workflowNodeSummaryText(summary: WorkflowNodeSummary) {
  if (summary.type === "expression")
    return `${summary.subject} ${summary.operator} ${formatWorkflowSummaryValue(summary.value, summary.unit)}`;
  return summary.fields
    .slice(0, 3)
    .map(
      (field) =>
        `${field.label}: ${formatWorkflowSummaryValue(field.value, field.unit)}`,
    )
    .join("; ");
}

export function outputPorts(
  node: WorkflowNode,
): { id: WorkflowPort; label: string }[] {
  if (node.kind === "sink" || node.kind === "failure") return [];
  if (node.kind === "condition")
    return [
      { id: "true", label: "Match" },
      { id: "false", label: "No match" },
      { id: "error", label: "Failure" },
    ];
  return [
    { id: "out", label: node.kind === "parallel" ? "Parallel" : "Output" },
    ...(node.kind === "trigger"
      ? []
      : [{ id: "error" as const, label: "Failure" }]),
  ];
}

/** Used by drag connections and the endpoint picker. */
export function connectionIssue(
  flow: WorkflowDefinition,
  edge: Omit<WorkflowEdge, "id">,
  ignoreId?: string,
): string | null {
  const source = flow.nodes.find((node) => node.id === edge.source);
  const target = flow.nodes.find((node) => node.id === edge.target);
  if (!source || !target) return "A connected node does not exist.";
  if (source.id === target.id) return "A node cannot connect to itself.";
  if (target.kind === "trigger")
    return "A trigger cannot receive an upstream connection.";
  if (!outputPorts(source).some((port) => port.id === edge.port))
    return "The source node does not have this output port.";
  const edges = flow.edges.filter((item) => item.id !== ignoreId);
  if (
    edges.some(
      (item) =>
        item.source === edge.source &&
        item.target === edge.target &&
        item.port === edge.port,
    )
  )
    return "This connection already exists.";
  const outputType = edge.port === "error" ? "error" : source.outputType;
  if (
    outputType &&
    target.inputType &&
    outputType !== "any" &&
    target.inputType !== "any" &&
    outputType !== target.inputType
  )
    return `Incompatible data types: ${outputType} → ${target.inputType}.`;
  if (
    target.kind !== "join" &&
    target.kind !== "failure" &&
    edges.some((item) => item.target === target.id)
  )
    return "Multiple inputs must be combined through a join node.";
  if (
    !(source.kind === "parallel" && edge.port === "out") &&
    edges.some((item) => item.source === source.id && item.port === edge.port)
  )
    return "An output port can connect to only one node. Use a parallel split for multiple branches.";
  const visited = new Set<string>();
  const queue = [target.id];
  while (queue.length) {
    const id = queue.pop()!;
    if (id === source.id) return "This connection would create a cycle.";
    if (visited.has(id)) continue;
    visited.add(id);
    queue.push(
      ...edges.filter((item) => item.source === id).map((item) => item.target),
    );
  }
  return null;
}

export type WorkflowEndpoint = { nodeId: string; port: WorkflowPort | "in" };

/** A normal occupied port inserts a step; parallel outputs and join inputs add branches. */
export function workflowStepContext(
  flow: WorkflowDefinition,
  endpoint: WorkflowEndpoint,
) {
  const node = flow.nodes.find((item) => item.id === endpoint.nodeId);
  const incoming = endpoint.port === "in";
  const edges = flow.edges.filter((edge) =>
    incoming
      ? edge.target === endpoint.nodeId
      : edge.source === endpoint.nodeId && edge.port === endpoint.port,
  );
  const branching = incoming
    ? node?.kind === "join" || node?.kind === "failure"
    : node?.kind === "parallel" && endpoint.port === "out";
  return {
    node,
    mode:
      edges.length && !branching
        ? ("insert" as const)
        : incoming
          ? ("before" as const)
          : ("after" as const),
    replace: branching ? [] : edges,
  };
}

/** Compute and validate the complete edit before changing the controlled graph. */
export function planWorkflowStep(
  flow: WorkflowDefinition,
  endpoint: WorkflowEndpoint,
  candidate: WorkflowNode,
  continuationPort?: WorkflowPort,
):
  | { issue: string }
  | { issue: null; remove: string[]; edges: Omit<WorkflowEdge, "id">[] } {
  const context = workflowStepContext(flow, endpoint);
  if (!context.node) return { issue: "A connected node does not exist." };
  if (endpoint.port === "in" && context.node.kind === "trigger")
    return { issue: "A trigger cannot receive an upstream connection." };
  if (context.replace.length > 1)
    return {
      issue:
        "This port has multiple connections. Resolve them before continuing.",
    };
  const exists = flow.nodes.some((node) => node.id === candidate.id);
  if (exists && context.mode === "insert")
    return { issue: "Choose a new node to insert a step." };
  const previous = context.replace[0];
  const edges: Omit<WorkflowEdge, "id">[] = [];
  if (endpoint.port === "in") {
    if (!continuationPort)
      return { issue: "Choose an output port for the new step." };
    if (previous)
      edges.push({
        source: previous.source,
        port: previous.port,
        target: candidate.id,
      });
    edges.push({
      source: candidate.id,
      port: continuationPort,
      target: context.node.id,
    });
  } else {
    edges.push({
      source: context.node.id,
      port: endpoint.port,
      target: candidate.id,
    });
    if (previous) {
      if (!continuationPort)
        return { issue: "Choose an output port for the new step." };
      edges.push({
        source: candidate.id,
        port: continuationPort,
        target: previous.target,
      });
    }
  }
  const remove = context.replace.map((edge) => edge.id);
  const draft: WorkflowDefinition = {
    ...flow,
    nodes: exists ? flow.nodes : [...flow.nodes, candidate],
    edges: flow.edges.filter((edge) => !remove.includes(edge.id)),
  };
  for (const [index, edge] of edges.entries()) {
    const issue = connectionIssue(draft, edge);
    if (issue) return { issue };
    draft.edges.push({ ...edge, id: `pending-${index}` });
  }
  return { issue: null, remove, edges };
}

/** Replace exactly one edge atomically, preserving sibling parallel branches. */
export function planWorkflowEdgeStep(
  flow: WorkflowDefinition,
  edgeId: string,
  candidate: WorkflowNode,
  continuationPort?: WorkflowPort,
): ReturnType<typeof planWorkflowStep> {
  const previous = flow.edges.find((edge) => edge.id === edgeId);
  if (!previous) return { issue: "The connection no longer exists." };
  if (flow.nodes.some((node) => node.id === candidate.id))
    return { issue: "Choose a new node to insert a step." };
  if (!continuationPort)
    return { issue: "Choose an output port for the new step." };
  const edges: Omit<WorkflowEdge, "id">[] = [
    { source: previous.source, port: previous.port, target: candidate.id },
    { source: candidate.id, port: continuationPort, target: previous.target },
  ];
  const draft = {
    ...flow,
    nodes: [...flow.nodes, candidate],
    edges: flow.edges.filter((edge) => edge.id !== edgeId),
  };
  for (const [index, edge] of edges.entries()) {
    const issue = connectionIssue(draft, edge);
    if (issue) return { issue };
    draft.edges.push({ ...edge, id: `pending-insert-${index}` });
  }
  return { issue: null, remove: [edgeId], edges };
}

/** Keep existing positions intact, leaving room for endpoint actions around the new node. */
export function placeWorkflowStep(
  flow: WorkflowDefinition,
  preferred: WorkflowNode["position"],
  dimensions: Record<string, { width: number; height: number }> = {},
): WorkflowNode["position"] {
  const width = 232;
  const height = Math.max(
    168,
    ...Object.values(dimensions).map((size) => size.height),
  );
  const stride = height + 112;
  for (let attempt = 0; attempt <= flow.nodes.length * 2 + 2; attempt++) {
    const offset = Math.ceil(attempt / 2) * (attempt % 2 ? 1 : -1) * stride;
    const position = { x: preferred.x, y: preferred.y + offset };
    const overlaps = flow.nodes.some((node) => {
      const size = dimensions[node.id] ?? { width, height };
      return (
        position.x < node.position.x + size.width + 128 &&
        position.x + width + 128 > node.position.x &&
        position.y < node.position.y + size.height + 112 &&
        position.y + height + 112 > node.position.y
      );
    });
    if (!overlaps) return position;
  }
  return {
    x: preferred.x,
    y: Math.max(0, ...flow.nodes.map((node) => node.position.y)) + stride,
  };
}

export function validateWorkflow(flow: WorkflowDefinition): WorkflowIssue[] {
  const issues: WorkflowIssue[] = [];
  const add = (
    code: string,
    message: string,
    nodeId?: string,
    edgeId?: string,
  ) => issues.push({ code, message, nodeId, edgeId });
  if (!flow.id.trim() || !flow.name.trim())
    add("identity", "Enter a workflow ID and name.");
  if (
    !Number.isInteger(flow.maxConcurrency) ||
    flow.maxConcurrency < 1 ||
    flow.maxConcurrency > 64
  )
    add(
      "concurrency",
      "The concurrency limit must be an integer from 1 to 64.",
    );
  if (!flow.nodes.length)
    add(
      "empty",
      "Add a trigger, processing steps and a destination to start building your workflow.",
    );
  if (!flow.nodes.some((node) => node.kind === "trigger"))
    add("trigger", "At least one trigger is required.");
  if (!flow.nodes.some((node) => node.kind === "sink"))
    add("sink", "At least one delivery node is required.");
  const nodeIds = new Set<string>();
  const edgeIds = new Set<string>();
  for (const node of flow.nodes) {
    if (nodeIds.has(node.id))
      add("duplicate-node", "Duplicate node ID.", node.id);
    nodeIds.add(node.id);
    if (!node.id.trim() || !node.label.trim() || !node.operation.trim())
      add(
        "node-label",
        "Node ID, name and operation ID are required.",
        node.id,
      );
    if (![node.position.x, node.position.y].every(Number.isFinite))
      add("position", "Node coordinates must be finite numbers.", node.id);
    if (
      !Number.isInteger(node.timeoutMs) ||
      node.timeoutMs < 1 ||
      !Number.isInteger(node.maxAttempts) ||
      node.maxAttempts < 1 ||
      node.maxAttempts > 10
    )
      add(
        "policy",
        "Timeout must be a positive integer. Maximum attempts must be an integer from 1 to 10.",
        node.id,
      );
    if (node.kind === "join" && !["all", "any"].includes(node.joinMode ?? ""))
      add(
        "join-mode",
        "Choose whether to wait for all inputs or any successful input.",
        node.id,
      );
    const keys = new Set<string>();
    for (const field of node.parameters) {
      if (!field.key.trim() || keys.has(field.key))
        add(
          "parameter-key",
          "Parameter keys must be nonempty and unique.",
          node.id,
        );
      keys.add(field.key);
      if (
        field.required &&
        (field.value === null || String(field.value).trim() === "")
      )
        add("required", `Enter a value for "${field.label}".`, node.id);
      if (
        field.type === "number" &&
        field.value !== null &&
        (typeof field.value !== "number" ||
          !Number.isFinite(field.value) ||
          (field.min !== undefined && field.value < field.min) ||
          (field.max !== undefined && field.value > field.max))
      )
        add(
          "number",
          `"${field.label}" is outside the allowed range.`,
          node.id,
        );
      if (
        field.type === "select" &&
        !field.options?.some((option) => option.value === field.value)
      )
        add("option", `"${field.label}" requires a valid option.`, node.id);
    }
    const incoming = flow.edges.filter((edge) => edge.target === node.id);
    const outgoing = flow.edges.filter((edge) => edge.source === node.id);
    if (node.kind !== "trigger" && !incoming.length)
      add("input", "This node needs an upstream input.", node.id);
    if (node.kind === "join" && incoming.length < 2)
      add("join-inputs", "A join needs at least two inputs.", node.id);
    if (
      node.kind === "parallel" &&
      outgoing.filter((edge) => edge.port === "out").length < 2
    )
      add(
        "parallel-outputs",
        "A parallel split needs at least two output branches.",
        node.id,
      );
    if (node.kind === "condition") {
      for (const port of ["true", "false"] as const)
        if (!outgoing.some((edge) => edge.port === port))
          add(
            "condition-output",
            `Connect the ${port === "true" ? "Match" : "No match"} output.`,
            node.id,
          );
    } else if (
      !["sink", "failure"].includes(node.kind) &&
      !outgoing.some((edge) => edge.port === "out")
    )
      add(
        "output",
        "This node needs a downstream step or destination.",
        node.id,
      );
  }
  for (const edge of flow.edges) {
    if (!edge.id.trim() || edgeIds.has(edge.id))
      add(
        "duplicate-edge",
        "Connection IDs must be nonempty and unique.",
        undefined,
        edge.id,
      );
    edgeIds.add(edge.id);
    const issue = connectionIssue(flow, edge, edge.id);
    if (issue) add("connection", issue, edge.target, edge.id);
  }
  const reached = new Set(
    flow.nodes.filter((node) => node.kind === "trigger").map((node) => node.id),
  );
  let changed = true;
  while (changed) {
    changed = false;
    for (const edge of flow.edges)
      if (reached.has(edge.source) && !reached.has(edge.target)) {
        reached.add(edge.target);
        changed = true;
      }
  }
  for (const node of flow.nodes)
    if (!reached.has(node.id))
      add(
        "unreachable",
        "This node cannot be reached from any trigger.",
        node.id,
      );
  return issues;
}

/** Layout only: positions are not physical coordinates or a measure of duration. */
export function layoutWorkflow(
  flow: WorkflowDefinition,
  sizes: Record<string, { height: number }> = {},
): WorkflowDefinition {
  const remaining = new Set(flow.nodes.map((node) => node.id));
  const levels = new Map<string, number>();
  for (let pass = 0; pass < flow.nodes.length && remaining.size; pass++) {
    for (const id of remaining) {
      const parents = flow.edges
        .filter((edge) => edge.target === id)
        .map((edge) => edge.source);
      if (parents.every((parent) => levels.has(parent))) {
        levels.set(
          id,
          parents.length
            ? Math.max(...parents.map((parent) => levels.get(parent)!)) + 1
            : 0,
        );
        remaining.delete(id);
      }
    }
  }
  const rows = new Map<number, number>();
  return {
    ...flow,
    nodes: flow.nodes.map((node) => {
      const level = levels.get(node.id) ?? 0;
      const row = rows.get(level) ?? 0;
      rows.set(level, row + (sizes[node.id]?.height ?? 168) + 112);
      return { ...node, position: { x: level * 360, y: row } };
    }),
  };
}

/** JSON import validates shape before any editor reads nested values. Invalid graphs remain editable. */
export function parseWorkflow(text: string): WorkflowDefinition {
  const value: unknown = JSON.parse(text);
  const object = (v: unknown): v is Record<string, unknown> =>
    v !== null && typeof v === "object" && !Array.isArray(v);
  const string = (v: unknown) => typeof v === "string";
  const optionalString = (v: unknown) => v === undefined || string(v);
  const finite = (v: unknown) => typeof v === "number" && Number.isFinite(v);
  if (
    !object(value) ||
    value.schemaVersion !== 1 ||
    !string(value.id) ||
    !string(value.name) ||
    !optionalString(value.description) ||
    !finite(value.maxConcurrency) ||
    !Array.isArray(value.nodes) ||
    !Array.isArray(value.edges)
  )
    throw new Error("Unsupported workflow file. Expected schemaVersion: 1.");
  if (value.nodes.length > 500 || value.edges.length > 2000)
    throw new Error("Import is limited to 500 nodes and 2,000 connections.");
  for (const node of value.nodes) {
    if (
      !object(node) ||
      !string(node.id) ||
      !string(node.label) ||
      !string(node.operation) ||
      !string(node.kind) ||
      !Object.hasOwn(workflowKinds, node.kind as string) ||
      !optionalString(node.description) ||
      !optionalString(node.inputType) ||
      !optionalString(node.outputType) ||
      !object(node.position) ||
      !finite(node.position.x) ||
      !finite(node.position.y) ||
      !finite(node.timeoutMs) ||
      !finite(node.maxAttempts) ||
      !Array.isArray(node.parameters) ||
      (node.joinMode !== undefined &&
        !["all", "any"].includes(node.joinMode as string))
    )
      throw new Error(
        "A node definition is incomplete or has an invalid type.",
      );
    for (const field of node.parameters) {
      if (
        !object(field) ||
        !string(field.key) ||
        !string(field.label) ||
        !["text", "number", "select"].includes(field.type as string) ||
        !(
          field.value === null ||
          string(field.value) ||
          finite(field.value) ||
          typeof field.value === "boolean"
        ) ||
        !optionalString(field.description) ||
        (field.required !== undefined && typeof field.required !== "boolean") ||
        (field.min !== undefined && !finite(field.min)) ||
        (field.max !== undefined && !finite(field.max)) ||
        (field.options !== undefined &&
          (!Array.isArray(field.options) ||
            !field.options.every(
              (option) =>
                object(option) && string(option.label) && string(option.value),
            )))
      )
        throw new Error("Invalid node parameter definition.");
    }
  }
  for (const edge of value.edges)
    if (
      !object(edge) ||
      !string(edge.id) ||
      !string(edge.source) ||
      !string(edge.target) ||
      !["out", "true", "false", "error"].includes(edge.port as string)
    )
      throw new Error("Invalid connection definition.");
  const flow = value as WorkflowDefinition;
  if (
    new Set(flow.nodes.map((node) => node.id)).size !== flow.nodes.length ||
    new Set(flow.edges.map((edge) => edge.id)).size !== flow.edges.length
  )
    throw new Error("Cannot import duplicate node or connection IDs.");
  return flow;
}

/** Positions are presentation state; editing them does not invalidate a run. */
export function workflowSignature(flow: WorkflowDefinition): string {
  return JSON.stringify({
    ...flow,
    nodes: flow.nodes.map(({ position: _position, ...node }) => node),
  });
}

/* A work surface, not a Panel. All control dimensions and materials belong to Graphite. */
.wf-root {
  container: workflow / inline-size;
  min-inline-size: 0;
  color: var(--foreground);
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--surface-radius, 12px);
  font-size: var(--body-font-size, 14px);
  line-height: 1.5;
  isolation: isolate;
}
.wf-root svg {
  flex-shrink: 0;
}
.wf-root button {
  cursor: pointer;
}
.wf-root button:disabled {
  cursor: not-allowed;
}
.wf-root
  :is(button, input, select, textarea, summary, pre, [tabindex]):focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 3px;
}
.wf-root :is(h3, h4, h5, p) {
  margin: 0;
}
.wf-root :is(h3, h4, h5) {
  font-size: inherit;
  font-weight: 550;
}
.wf-root :is(p, dd, small, strong) {
  overflow-wrap: anywhere;
}
.wf-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  padding: 16px 20px;
  border-block-end: 1px solid var(--border);
}
.wf-identity {
  display: flex;
  align-items: center;
  gap: 12px;
  min-inline-size: 0;
  flex: 1 1 240px;
}
.wf-identity-icon.surface-control {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  inline-size: 40px;
  block-size: 40px;
  border: 1px solid var(--control-edge, var(--border));
  border-radius: 50%;
  background-color: var(--secondary);
  color: var(--secondary-foreground);
  box-shadow: var(--shadow-control);
  cursor: default;
}
.wf-identity-icon > svg {
  inline-size: 16px;
  block-size: 16px;
}
.wf-identity > div {
  min-inline-size: 0;
}
.wf-identity h3 {
  font-size: var(--body-font-size, 14px);
  overflow-wrap: anywhere;
}
.wf-header-states {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px 16px;
  margin-block-start: 3px;
  font-size: var(--tag-font-size, 12px);
  color: var(--muted-foreground);
}
.wf-header-state {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-inline-size: max(24px, var(--control-hit-height, 0px));
  min-block-size: max(24px, var(--control-hit-height, 0px));
  padding: 0;
  border: 0;
  border-radius: var(--field-radius, 6px);
  background: transparent;
  font: inherit;
  color: inherit;
  white-space: nowrap;
  cursor: default;
  -webkit-touch-callout: none;
}
.wf-header-state > svg {
  inline-size: 14px;
  block-size: 14px;
  stroke-width: 1.75;
}
.wf-header-state-value {
  font-variant-numeric: tabular-nums;
}
.wf-header-state:is([data-state="published"], [data-state="valid"]) > svg {
  color: var(
    --success-text,
    color-mix(in srgb, var(--success, var(--foreground)) 80%, var(--foreground))
  );
}
.wf-header-state:is([data-state="changed"], [data-state="warning"]) > svg {
  color: var(
    --warning-text,
    color-mix(in srgb, var(--warning, var(--foreground)) 72%, var(--foreground))
  );
}
.wf-header-state[data-state="invalid"] {
  color: color-mix(in srgb, var(--destructive) 85%, var(--foreground));
}
.wf-icon-toolbar {
  display: flex;
  align-items: center;
  flex-wrap: nowrap;
  inline-size: max-content;
  max-inline-size: 100%;
  gap: 4px;
  padding: 5px;
  border: 0;
  border-radius: 999px;
}
.wf-icon-toolbar:empty {
  display: none;
}
/* Count actual icon actions, not zoom readouts, tooltip portals or disabled
 * states. Three or more related actions share one shell; a pair stays separate. */
.wf-icon-toolbar:not([data-grouping="separate"]):has(
    > :nth-child(3 of [data-slot="button"][data-size^="icon"]:not([hidden]))
  ) {
  padding: 4px;
  border: 1px solid var(--border);
  background: var(--card);
  box-shadow: var(--shadow-surface);
}
.wf-actions {
  flex-shrink: 0;
  flex-wrap: wrap;
  padding: 0;
}
.wf-tooltip {
  z-index: 90;
  display: flex;
  align-items: center;
  gap: 12px;
  max-inline-size: min(280px, calc(100vw - 24px));
  padding: 6px 10px;
  border: 1px solid var(--surface-edge);
  border-radius: var(--field-radius, 6px);
  background: linear-gradient(
    155deg,
    var(--popover-top),
    var(--popover-bottom)
  );
  color: var(--popover-foreground);
  box-shadow: var(--shadow-menu);
  font-size: var(--body-font-size, 14px);
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.wf-tooltip kbd {
  color: var(--muted-foreground);
  font-family: inherit;
  white-space: nowrap;
}
.wf-menu {
  z-index: 80;
  min-inline-size: 180px;
  max-inline-size: min(300px, calc(100vw - 24px));
  max-block-size: var(--radix-dropdown-menu-content-available-height, 480px);
  overflow-y: auto;
  overscroll-behavior: contain;
}
.wf-context-anchor {
  position: fixed;
  inline-size: 0;
  block-size: 0;
  pointer-events: none;
}
.wf-menu-label {
  padding: 6px 8px;
  color: var(--muted-foreground);
  font-size: var(--tag-font-size, 12px);
  overflow-wrap: anywhere;
}
.wf-menu [data-slot="dropdown-menu-item"] {
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: default;
}
.wf-menu svg {
  inline-size: 16px;
  block-size: 16px;
}
.wf-stage {
  position: relative;
  min-inline-size: 0;
}
.wf-canvas {
  position: relative;
  block-size: 690px;
  min-inline-size: 0;
  background: var(--background);
}
.wf-stage[data-right="true"] > .wf-canvas {
  margin-inline-end: 320px;
}
.wf-canvas:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
}
.wf-canvas .react-flow__edge {
  cursor: pointer;
}
.wf-canvas .react-flow__edgeupdater {
  fill: var(--card);
  stroke: var(--foreground);
  stroke-width: 1.5;
  cursor: grab;
}
.wf-canvas .react-flow__edgeupdater:active {
  cursor: grabbing;
}
.wf-canvas .react-flow__edge:hover .react-flow__edge-path {
  stroke: var(--foreground);
  stroke-width: 2;
}
.wf-canvas
  .react-flow__edge:is(.selected, :focus-visible)
  .react-flow__edge-path {
  stroke: var(--foreground);
  stroke-width: 2.5;
}
.wf-canvas .react-flow {
  --xy-background-color: var(--background);
  --xy-background-pattern-dots-color: var(--border);
  --xy-edge-stroke: var(--muted-foreground);
  --xy-edge-stroke-width: 1.5;
  --xy-edge-stroke-selected: var(--foreground);
  --xy-edge-label-background-color: var(--background);
  --xy-edge-label-color: var(--foreground);
  --xy-minimap-background-color: var(--card);
  --xy-attribution-background-color: var(--background);
}
.wf-canvas .react-flow__attribution a {
  color: var(--muted-foreground);
}
.wf-canvas .react-flow__minimap {
  margin: 14px 14px 28px;
  border-radius: var(--button-radius, 6px);
  border: 1px solid var(--border);
  overflow: clip;
}
.wf-canvas .react-flow__edge-text {
  font-size: var(--body-font-size, 14px);
}
.wf-canvas .wf-error-edge .react-flow__edge-path {
  stroke-dasharray: 5 5;
}
.wf-canvas-toolbar,
.wf-zoom-controls {
  position: absolute;
  z-index: 5;
}
.wf-canvas-toolbar {
  inset-block-start: 14px;
  inset-inline-start: 14px;
}
.wf-zoom-controls {
  inset-block-end: 14px;
  inset-inline-start: 14px;
}
.wf-zoom-value {
  display: grid;
  place-items: center;
  flex: none;
  inline-size: 5ch;
  color: var(--foreground);
  font-size: var(--tag-font-size, 12px);
  font-variant-numeric: tabular-nums;
  line-height: 1.5;
  text-align: center;
  white-space: nowrap;
}
.wf-node {
  inline-size: 232px;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: var(--surface-radius, 12px);
  background: var(--card);
  color: var(--card-foreground);
  box-shadow: var(--shadow-surface);
}
.wf-node-heading {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}
.wf-node-icon {
  display: grid;
  place-items: center;
  inline-size: 30px;
  block-size: 30px;
  margin-block-start: 4px;
  flex-shrink: 0;
  color: var(--foreground);
}
.wf-node-icon svg {
  inline-size: 20px;
  block-size: 20px;
}
.wf-node-title {
  min-inline-size: 0;
  display: grid;
  gap: 3px;
}
.wf-node-title small {
  color: var(--muted-foreground);
  font-size: var(--tag-font-size, 12px);
  line-height: 1.3;
}
.wf-node-title strong {
  font-size: var(--body-font-size, 14px);
  font-weight: 550;
  line-height: 1.4;
}
/* Full names remain in the node's accessible name and editable name field. */
.wf-node-title strong,
.wf-drawer-heading h4,
.wf-identity h3 {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  line-clamp: 2;
  overflow: hidden;
}
.wf-node-summary {
  margin: 10px 0 0;
  font-size: var(--tag-font-size, 12px);
  line-height: 1.5;
  font-variant-numeric: tabular-nums;
}
.wf-node-fields {
  display: grid;
  gap: 4px;
}
.wf-node-fields:empty {
  display: none;
}
.wf-node-fields > div {
  display: grid;
  grid-template-columns: 6.5em minmax(0, 1fr);
  gap: 10px;
}
.wf-node-fields :is(dt, dd),
.wf-node-expression > :is(span, strong) {
  min-inline-size: 0;
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.wf-node-fields dt,
.wf-node-expression > span {
  color: var(--muted-foreground);
}
.wf-node-fields dd {
  color: var(--card-foreground);
}
.wf-node-expression > span {
  display: block;
}
.wf-node-expression > strong {
  display: block;
  margin-block-start: 4px;
  font-size: var(--body-font-size, 14px);
  font-weight: 550;
  color: var(--card-foreground);
}
.wf-node-operator {
  margin-inline-end: 8px;
}
.wf-node[data-selected="true"] {
  outline: 2px solid var(--ring);
  outline-offset: 3px;
}
.wf-node[data-status="running"] {
  outline: 2px solid var(--foreground);
  outline-offset: 2px;
}
.wf-node[data-status="failed"] {
  outline: 1px solid var(--destructive);
  outline-offset: 1px;
}
.wf-node-result {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 6px;
  margin-block-start: 10px;
  padding-block-start: 9px;
  border-block-start: 1px solid var(--border);
  font-size: var(--tag-font-size, 12px);
}
.wf-node-result > span:last-child {
  color: var(--muted-foreground);
  font-variant-numeric: tabular-nums;
}
.wf-issue-icon {
  inline-size: 16px;
  block-size: 16px;
  margin-inline-start: auto;
  color: var(--warning-text, var(--foreground));
}
.wf-node .react-flow__handle {
  inline-size: 9px;
  block-size: 9px;
  background: var(--muted-foreground);
  background: linear-gradient(
    145deg,
    color-mix(in srgb, var(--muted-foreground) 75%, var(--foreground)),
    var(--muted-foreground) 55%,
    color-mix(in srgb, var(--muted-foreground) 88%, var(--background))
  );
  border: 2px solid var(--card);
  box-shadow:
    inset 0 0.5px 0.5px rgb(255 255 255 / 0.3),
    inset 0 -0.5px 0.5px rgb(0 0 0 / 0.28);
}
.wf-node .wf-handle-error {
  border: 1.5px solid transparent;
  background:
    linear-gradient(var(--card), var(--card)) padding-box,
    linear-gradient(
        145deg,
        color-mix(in srgb, var(--muted-foreground) 75%, var(--foreground)),
        var(--muted-foreground) 55%,
        color-mix(in srgb, var(--muted-foreground) 88%, var(--background))
      )
      border-box;
  box-shadow: inset 0 0.5px 1px rgb(0 0 0 / 0.3);
}
.wf-node .react-flow__handle::after {
  content: "";
  position: absolute;
  inline-size: 40px;
  block-size: 40px;
  inset: 50% auto auto 50%;
  transform: translate(-50%, -50%);
}
.wf-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--muted-foreground);
  white-space: nowrap;
}
.wf-status > svg {
  inline-size: 14px;
  block-size: 14px;
}
.wf-status[data-status="succeeded"] {
  color: var(--success-text, var(--foreground));
}
.wf-status[data-status="failed"] {
  color: var(--destructive, var(--foreground));
}
.wf-status[data-status="running"] {
  color: var(--foreground);
}
.wf-empty {
  position: absolute;
  inset: 50% 20px auto;
  transform: translateY(-50%);
  display: grid;
  justify-items: center;
  text-align: center;
  gap: 12px;
  pointer-events: none;
}
.wf-start-node {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  inline-size: 232px;
  min-block-size: 168px;
  max-inline-size: 100%;
  padding: 24px;
  border: 1px dashed var(--muted-foreground);
  border-radius: var(--surface-radius, 12px);
  background: var(--card);
  color: var(--foreground);
  font: inherit;
  pointer-events: auto;
  transition: background-color var(--transition-duration, 140ms);
}
